import {Config, Field} from 'alinea'

export default Config.type('Object field', {
  fields: {
    object: Field.object('Address', {
      fields: {
        street: Field.text('Street'),
        zip: Field.text('Zip code', {width: 0.5}),
        city: Field.text('City', {width: 0.5})
      }
    })
  }
})

import {cms} from '@/cms'
import {Config, Field} from 'alinea'

export const Venue = Config.document('Venue', {
  fields: {
    address: Field.object('Address', {
      fields: {
        street: Field.text('Street'),
        city: Field.text('City')
      }
    })
  }
})

const venuesInGhent = await cms.find({
  type: Venue,
  filter: {address: {has: {city: 'Ghent'}}},
  select: {address: Venue.address}
})

import {Config, Field} from 'alinea'

function cta(label: string) {
  return Field.object(label, {
    fields: {
      label: Field.text('Label', {width: 0.5}),
      link: Field.link('Link', {width: 0.5})
    }
  })
}

export const Hero = Config.type('Hero', {
  fields: {
    title: Field.text('Title'),
    primary: cta('Primary button'),
    secondary: cta('Secondary button')
  }
})
